"use client"

import Link from "next/link"
import { useSearchParams } from "next/navigation"
import { Suspense, useEffect, useState } from "react"

// Base path where certificates are stored
const CERTIFICATE_BASE_PATH = "/content/noc/NOC24/SEM2/Ecertificates/109/noc24-hs159/Course"

function CertificateViewer() {
  const searchParams = useSearchParams()
  const certificateId = searchParams.get("q")?.trim() || ""
  const [isValidId, setIsValidId] = useState(false)
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    const checkCertificate = async () => {
      if (!certificateId) {
        setIsValidId(false)
        setIsLoading(false)
        return
      }

      try {
        // Try to fetch the certificate to check if it exists
        const response = await fetch(`${CERTIFICATE_BASE_PATH}/${encodeURIComponent(certificateId)}.pdf`)
        if (response.ok) {
          setIsValidId(true)
          setError(null)
        } else if (response.status === 404) {
          setIsValidId(false)
          setError('CERTIFICATE_NOT_FOUND')
        } else {
          setIsValidId(false)
          setError('ERROR_FETCHING')
        }
      } catch (err) {
        console.error('Error checking certificate:', err)
        setIsValidId(false)
        setError('ERROR_FETCHING')
      } finally {
        setIsLoading(false)
      }
    }

    checkCertificate()
  }, [certificateId])

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white">
        <div className="animate-pulse">Loading certificate...</div>
      </div>
    )
  }

  if (!isValidId && !isLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-white p-6 text-center">
        <div className="max-w-md w-full bg-white rounded-lg shadow-sm p-8">
          <div className="text-center">
            <div className="text-2xl font-medium text-gray-800 mb-4">
              {error === 'CERTIFICATE_NOT_FOUND' 
                ? "Sorry you don't have a Certificate!" 
                : "Error Loading Certificate"}
            </div>
            <p className="text-gray-600 mb-6">
              {error === 'CERTIFICATE_NOT_FOUND'
                ? `The certificate ID "${certificateId}" was not found in our records.`
                : "There was an error loading the certificate. Please try again later."}
            </p>
            <div className="mt-6 p-4 bg-gray-50 rounded-md">
              <p className="text-sm text-gray-600">
                Please contact support for assistance:
              </p>
              <a 
                href="mailto:support@nptel.iitm.ac.in" 
                className="text-blue-600 hover:underline text-sm"
              >
                support@nptel.iitm.ac.in
              </a>
            </div>
            <div className="mt-8">
              <Link 
                href="/" 
                className="text-blue-600 hover:underline text-sm"
              >
                ← Back to Home
              </Link>
            </div>
          </div>
        </div>
      </div>
    )
  }

  const certificateUrl = `${CERTIFICATE_BASE_PATH}/${encodeURIComponent(certificateId)}.pdf`

  return (
    <div className="min-h-screen flex items-center justify-center bg-white">
      <a
        href={certificateUrl}
        target="_blank"
        rel="noopener noreferrer"
        className="px-8 py-2 rounded-lg bg-blue-600 text-white text-sm font-medium hover:bg-blue-700 transition-colors"
      >
        Course Certificate
      </a>
    </div>
  )
}

export default function EcertificatePage() {
  return (
    <Suspense fallback={
      <div className="min-h-screen flex items-center justify-center bg-white">
        <div className="animate-pulse">Loading certificate...</div>
      </div>
    }>
      <CertificateViewer />
    </Suspense>
  )
}
